import {questionVisual,optionVisual} from './quiz-visuals.js?v=cards-no-arrows-20261008';
import {activityDifficulty} from './xp.js';
import {t} from './i18n.js?v=cards-no-arrows-20261008';
import {results,record,percent,pendingCount,autoSave} from './progress.js?v=3ce5c6a';
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let session;
export function sourceQuiz(questions,module='practice',theme='decisions',filters=null){session={questions,module,theme,filters,filter:'RANDOM',index:0,answers:new Map(),selected:[],saved:true,id:crypto.randomUUID()};return `<section class="quiz-player">${view()}</section>`}
function view(){const s=session,q=s.questions[s.index],difficulty=activityDifficulty(q,s.theme),answered=s.answers.get(s.index),items=q.type==='sequence'?[...(q.items||q.answer)].reverse():q.options||[];const presentation=questionVisual(q,s.module);const latest=new Map(results().filter(x=>x.module===s.module).map(x=>[x.question,x]));const done=latest.size,correct=[...latest.values()].filter(x=>x.correct).length;
return `<div class="quiz-counters">${[[t('stats.correct'),correct,percent(correct,done)],[t('stats.done'),done,percent(done,s.questions.length)],[t('stats.total'),s.questions.length,100]].map(([label,n,p])=>`<article><span>${label}</span><strong>${n}</strong><small>${p}%</small></article>`).join('')}</div>${s.filters?`<div class="modality-filters" role="group" aria-label="FILTRAR MODALIDADE">${s.filters.options.map(o=>`<button type="button" data-modality-filter="${escape(o)}" aria-pressed="${s.filter===o}">${escape(o)}</button>`).join('')}</div>`:''}<div class="source-question"><span class="eyebrow">${s.index+1} / ${s.questions.length} · ${t('xp.'+difficulty.key)} · ${difficulty.xp} XP</span><h2>${escape(presentation.prompt)}</h2>${presentation.html}${q.type==='sequence'?`<p>${t('quiz.sequence')}</p>`:''}<div class="quiz-options">${items.map((item,i)=>`<button type="button" data-quiz-option="${i}" ${answered||s.selected.includes(i)?'disabled':''}>${optionVisual(item)}</button>`).join('')}</div>${s.selected.length?`<p>${s.selected.map(i=>escape(items[i])).join(' → ')}</p>`:''}${answered?`<div class="quiz-feedback" role="status"><strong>${t(answered.correct?'quiz.correct':'quiz.incorrect')} ${answered.correct?'+'+difficulty.xp+' XP':''}</strong><p>${t('quiz.answer')}: ${escape(Array.isArray(q.answer)?q.answer.join(' → '):q.answer)}</p><p>${escape(q.analysis||q.why||'')}</p></div>`:''}</div>${(!autoSave()||pendingCount())?`<button class="save-activities" data-save-activities>${t('training.saveNow')}</button><p class="stats-storage">${t('training.temporary')}</p>`:''}<div class="quiz-controls"><button data-quiz-exit>${t('stats.exit')}</button><button data-quiz-review ${s.index===0?'disabled':''}>${t('stats.review')}</button><button data-quiz-next>${t(s.index===s.questions.length-1?'stats.finish':'stats.next')}</button></div>`}
function refresh(){const player=document.querySelector('.quiz-player');if(player)player.innerHTML=view()}
document.addEventListener('click',event=>{const button=event.target.closest('[data-quiz-option],[data-quiz-exit],[data-quiz-review],[data-quiz-next],[data-modality-filter]');if(!button||!button.closest('.quiz-player')||!session)return;const s=session;
if(button.hasAttribute('data-modality-filter')){const key=button.dataset.modalityFilter;if(!s.filters?.options.includes(key))return;s.filter=key;s.questions=s.filters.select(key);s.index=0;s.answers=new Map();s.selected=[];refresh();return}
if(button.hasAttribute('data-quiz-exit')){session=null;location.hash='practice';return}
if(button.hasAttribute('data-quiz-review')){if(s.index>0)s.index--;s.selected=[];refresh();return}
if(button.hasAttribute('data-quiz-next')){if(s.index===s.questions.length-1){session=null;location.hash='evolution';return}s.index++;s.selected=[];refresh();return}
if(s.answers.has(s.index))return;const q=s.questions[s.index],items=q.type==='sequence'?[...(q.items||q.answer)].reverse():q.options||[];const index=Number(button.dataset.quizOption);if(s.selected.includes(index))return;let answer=items[index];if(q.type==='sequence'){s.selected.push(index);if(s.selected.length<items.length){refresh();return}answer=s.selected.map(i=>items[i])}const correct=JSON.stringify(answer)===JSON.stringify(q.answer);s.answers.set(s.index,{correct});s.saved=record({module:s.module,theme:s.theme,session:s.id,question:String(q.id||s.index),correct,xp:correct?activityDifficulty(q,s.theme).xp:0,difficulty:activityDifficulty(q,s.theme).key});refresh();});

window.addEventListener('academy:activities-saved',()=>{if(session)refresh()});
